create or replace function public.operation_storage_usage() returns jsonb language plpgsql stable security invoker set search_path = '' as $$ begin if not private.is_operation_admin() then raise exception 'Acesso restrito ao administrador' using errcode = '42501'; end if; return (select jsonb_build_object('bytes',coalesce(sum(coalesce((metadata->>'size')::bigint,0)),0),'files',count(*)) from storage.objects where bucket_id='evidencias'); end $$; revoke all on function public.operation_storage_usage() from public, anon; grant execute on function public.operation_storage_usage() to authenticated;